class Solution {
public:
    bool isConsecutive(vector<int>& nums) {
        int mn = *min_element(nums.begin(), nums.end());
        int n = nums.size();
        int mx = mn + n - 1;
        for (auto &v : nums) {
            int num = abs(v);
            if (num > mx) return false;
            nums[num - mn] *= -1;
        }
        int cnt = 0;
        for (auto &v : nums) {
            if (v == 0) {
                cnt++;
                continue;
            }
            if (v > 0) return false;
        }
        if (cnt > 1) return false; 
        return true;
    }
};

class Solution:
    def isConsecutive(self, nums: List[int]) -> bool:
        mi, mx = min(nums), max(nums)
        return len(set(nums)) == mx - mi + 1 == len(nums)

class Solution {
    public boolean isConsecutive(int[] nums) {
        int mi = nums[0], mx = 0;
        Set<Integer> s = new HashSet<>();
        for (int x : nums) {
            if (!s.add(x)) {
                return false;
            }
            mi = Math.min(mi, x);
            mx = Math.max(mx, x);
        }
        return mx - mi + 1 == nums.length;
    }
}

class Solution {
public:
    bool isConsecutive(vector<int>& nums) {
        unordered_set<int> s;
        int mi = nums[0], mx = 0;
        for (int x : nums) {
            if (s.contains(x)) {
                return false;
            }
            s.insert(x);
            mi = min(mi, x);
            mx = max(mx, x);
        }
        return mx - mi + 1 == nums.size();
    }
};

